import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    counted = df[df['row_kind'] == 'counted'].copy()
except Exception:
    counted = df.copy()

try:
    for col in ['Billed Amount', 'Allowed Amount', 'Paid Amount', 'Claim Total Billed', 'Adjustment Seq']:
        counted[col] = pd.to_numeric(counted[col], errors='coerce')
    for col in ['Service From', 'Paid Date']:
        counted[col] = pd.to_datetime(counted[col], errors='coerce')
except Exception:
    pass

# EDA
try:
    metric_cols = ['Adjustment Seq', 'Billed Amount', 'Allowed Amount', 'Paid Amount', 'Claim Total Billed']
    for col in metric_cols:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# CORRELATIONS
try:
    num_cols = ['Adjustment Seq', 'Billed Amount', 'Allowed Amount', 'Paid Amount', 'Claim Total Billed']
    corr_df = counted[num_cols].dropna()
    for i, c1 in enumerate(num_cols):
        for c2 in num_cols[i+1:]:
            pair = corr_df[[c1, c2]].dropna()
            if len(pair) > 1:
                r = float(pair[c1].corr(pair[c2]))
                if abs(r) >= 0.2:
                    result['correlations'][f'{c1}__{c2}'] = round(r, 4)
except Exception:
    pass

# SEGMENTATION
try:
    seg_cols = ['Payer', 'Claim Status', 'Place of Service']
    money_cols = ['Billed Amount', 'Allowed Amount', 'Paid Amount']
    for seg in seg_cols:
        for met in money_cols:
            grp = counted.groupby(seg)[met].sum().nlargest(10)
            result['segments'].append({
                'segment_column': seg, 'metric_column': met,
                'aggregation': 'sum', 'label': None,
                'results': [{'name': str(k), 'value': round(float(v), 2)} for k, v in grp.items()]
            })
        claim_counts = counted.groupby(seg)['Claim ID'].nunique().nlargest(10)
        result['segments'].append({
            'segment_column': seg, 'metric_column': 'Claim ID',
            'aggregation': 'count', 'label': 'distinct_claims',
            'results': [{'name': str(k), 'value': int(v)} for k, v in claim_counts.items()]
        })
    # Denial rate by Payer
    non_pending = counted[counted['Claim Status'] != 'Pending']
    denied = non_pending[non_pending['Claim Status'].str.lower().isin(['denied', 'deny', 'rejection', 'rejected'])]
    for payer, grp in non_pending.groupby('Payer'):
        total_claims = grp['Claim ID'].nunique()
        denied_claims = denied[denied['Payer'] == payer]['Claim ID'].nunique()
        if total_claims > 0:
            pass
    denial_by_payer = []
    for payer, grp in non_pending.groupby('Payer'):
        total = grp['Claim ID'].nunique()
        den = denied[denied['Payer'] == payer]['Claim ID'].nunique()
        denial_by_payer.append({'name': str(payer), 'value': round(den / total, 4) if total > 0 else 0.0})
    denial_by_payer_sorted = sorted(denial_by_payer, key=lambda x: -x['value'])[:10]
    result['segments'].append({
        'segment_column': 'Payer', 'metric_column': 'Claim Status',
        'aggregation': 'ratio', 'label': 'denial_rate',
        'results': denial_by_payer_sorted
    })
except Exception:
    pass

# ANOMALIES
try:
    import numpy as np
    anomaly_cols = ['Billed Amount', 'Allowed Amount', 'Paid Amount', 'Claim Total Billed']
    all_anomalies = []
    for col in anomaly_cols:
        s = counted[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0.0
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()))
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo_t, hi_t = q1 - 3 * iqr, q3 + 3 * iqr
        mask = (s_t < lo_t) | (s_t > hi_t)
        pct = mask.sum() / len(s_t)
        if pct > 0.05:
            all_anomalies.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} flags >{pct*100:.1f}% of values as extreme; heavy-tailed natural distribution, not anomalies'
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_t) - shift)
            hi_orig = float(np.expm1(hi_t) - shift)
        else:
            lo_orig, hi_orig = lo_t, hi_t
        exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
        flagged_idx = s_t[mask].index.tolist()
        for idx in flagged_idx[:5]:
            raw_val = float(counted.loc[idx, col])
            t_val = float(s_t.loc[idx])
            if t_val > q3 + 5 * iqr or t_val < q1 - 5 * iqr:
                sev = 'critical'
            elif t_val > q3 + 4 * iqr or t_val < q1 - 4 * iqr:
                sev = 'high'
            else:
                sev = 'medium'
            all_anomalies.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val:.2f} lies outside expected range {exp_range}'
            })
    result['anomalies'] = all_anomalies[:25]
except Exception:
    pass

# TRENDS
try:
    counted['svc_month'] = counted['Service From'].dt.to_period('M')
    monthly = counted.groupby('svc_month').agg(
        billed=('Billed Amount', 'sum'),
        allowed=('Allowed Amount', 'sum'),
        paid=('Paid Amount', 'sum')
    ).sort_index()
    if len(monthly) >= 2:
        for col_key, col_label in [('billed', 'Billed Amount'), ('allowed', 'Allowed Amount'), ('paid', 'Paid Amount')]:
            vals = monthly[col_key]
            pct = float((vals.iloc[-1] - vals.iloc[-2]) / vals.iloc[-2] * 100) if vals.iloc[-2] != 0 else 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': col_label, 'period': 'MoM', 'direction': direction,
                'pct_change': round(pct, 2), 'segment': None
            })
except Exception:
    pass

# FORECASTING (simple linear extrapolation on paid amount)
try:
    from scipy import stats as sp_stats
    monthly_paid = counted.groupby(counted['Service From'].dt.to_period('M'))['Paid Amount'].sum().sort_index()
    if len(monthly_paid) >= 3:
        x = list(range(len(monthly_paid)))
        y = monthly_paid.values.astype(float)
        slope, intercept, _, _, _ = sp_stats.linregress(x, y)
        next_periods = []
        last_period = monthly_paid.index[-1]
        for i in range(1, 4):
            future_x = len(monthly_paid) - 1 + i
            future_val = float(intercept + slope * future_x)
            future_period = str(last_period + i)
            next_periods.append({'period': future_period, 'value': round(future_val, 2)})
        result['forecast_points'] = next_periods
except Exception:
    pass

result['assumptions'] = [
    "Only 'counted' row_kind rows used for segmentation, trends, anomalies, and forecasting.",
    "Denial rate excludes pending claims; denied = Claim Status in ['denied','rejected'].",
    "Anomaly detection uses log1p transform for skewed columns (|skew|>2).",
    "Forecasting uses OLS linear regression on monthly paid totals; assumes linear trend.",
    "Claim-level metrics use distinct Claim ID counts; money metrics are line-level sums."
]

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

